function dump(node, depth) {
  if (!node || depth > 4) return null;
  const o = { id: node.id, type: node.type, name: node.name, w: Math.round(node.width||0), h: Math.round(node.height||0) };
  if ('fills' in node && Array.isArray(node.fills)) o.fills = node.fills.map(f => ({t:f.type, c:f.color, o:f.opacity}));
  if (node.type === 'TEXT') { o.chars = node.characters; o.font = node.fontName; o.size = node.fontSize; }
  if ('cornerRadius' in node) o.radius = node.cornerRadius;
  if ('children' in node && depth < 4) o.children = node.children.map(c => dump(c, depth+1));
  return o;
}
