function forEachInstance(node, mainId, cb){ if(!node) return; if(node.type==='INSTANCE'&&node.mainComponent&&node.mainComponent.id===mainId){ cb(node); return; } if('children'in node) node.children.forEach(c=>forEachInstance(c,mainId,cb)); }
